artifact.schema:
// ─── CAPABILITY TOKEN ───────────────────────────────────────────────
export type CapabilityToken = `${string}:${'read' | 'write' | 'stream'}`;

// ─── CAPABILITY DEFINITION ──────────────────────────────────────────
export interface CapabilityDefinition<TApi> {
  readonly token:    CapabilityToken;
  readonly factory:  (deps: ProviderDeps) => TApi;
  readonly runtime?: 'client' | 'server' | 'edge';  // SSR optimization hint
}

// ─── PROVIDER DEFINITION ────────────────────────────────────────────
export interface ProviderDefinition {
  readonly id:           string;
  readonly version:      `${number}.${number}.${number}`;
  readonly capabilities: Record<CapabilityToken, CapabilityDefinition<unknown>>;
  readonly Provider:     ComponentType<{ children: ReactNode; config: unknown }>;
  readonly configSchema: ZodSchema;
  readonly experimental?: { signals?: boolean; suspenseRead?: boolean };
}

export function defineProvider(spec: ProviderDefinition): ProviderDefinition;

artifact.capability-example:
// packages/providers/products-localstorage/src/index.ts
import { defineProvider } from '@surte/core';
import { z } from 'zod';

export const productsLocalStorageProvider = defineProvider({
  id:      'products',
  version: '1.0.0',

  configSchema: z.object({
    seed:       z.array(ProductSchema).optional(),
    storageKey: z.string().default('inventory:products'),
  }),

  capabilities: {
    'products:read': {
      token: 'products:read',
      runtime: 'client',
      factory: ({ store }) => ({
        list:  (q?: ListQuery) => store.list(q),
        get:   (id: string)    => store.get(id),
        count: ()              => store.count(),
      }),
    },
    'products:write': {
      token: 'products:write',
      runtime: 'client',
      factory: ({ store }) => ({
        create: (input: NewProduct)        => store.create(input),
        update: (id: string, patch: Patch) => store.update(id, patch),
        remove: (id: string)               => store.remove(id),
      }),
    },
    'products:stream': {
      token: 'products:stream',
      runtime: 'client',
      factory: ({ store }) => ({
        subscribe: (listener) => store.subscribe(listener),
      }),
    },
  },

  Provider: ProductsLocalStorageProvider,    // React component
});

artifact.pattern-consumer-example:
// ProductTablePattern only needs READ — no write deps leaked
const ProductTablePattern = definePattern({
  // ...
  requires: ['products:read', 'session:read'] as const,
  // ...
});

// ProductFormPattern needs both
const ProductFormPattern = definePattern({
  // ...
  requires: ['products:read', 'products:write', 'session:read'] as const,
  // ...
});
